#!/usr/bin/env bash
set -euo pipefail

# Usage: bin/generate_package.sh <release-tag>
TAG=${1:?release tag required}
ROOT_PATH=$(cd "$(dirname "$0")/.." && pwd)
BASE_URL="https://github.com/${GITHUB_REPOSITORY:-amine2233/libgit2-spm}/releases/download/$TAG"

target() {
    printf '\t\t.binaryTarget(\n\t\t\tname: "%s",\n\t\t\turl: "%s/%s.zip",\n\t\t\tchecksum: "%s"\n\t\t),\n' \
        "$1" "$BASE_URL" "$1" "$(swift package compute-checksum "$ROOT_PATH/lib/$1.zip")"
}

{
    cat <<'HEAD'
// swift-tools-version:5.3
// Generated by bin/generate_package.sh. Do not edit by hand.

import PackageDescription

let package = Package(
	name: "libgit2",
	platforms: [.iOS(.v13), .macOS(.v10_15)],
	products: [
		.library(
			name: "libgit2",
			targets: [
				"libgit2",
				"libssh2",
				"libssl",
				"libcrypto"
			]
		),
	],
	dependencies: [],
	targets: [
HEAD
    for lib in libgit2 libssh2 libssl libcrypto; do target "$lib"; done
    printf '\t]\n)\n'
} > "$ROOT_PATH/Package.swift"
